const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const subcategory = String(row.Subcategory || '').trim();

// Extract the LAST TASK: ... SOLUTION: block if present (Cat 2-style inputs)
let task = '';
const re = /TASK:\s*([\s\S]*?)\s*SOLUTION:/g;
let m, last = null;
while ((m = re.exec(inputText)) !== null) last = m[1];
task = last ? last.trim() : inputText;

const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayWeekday = weekdays[today.getDay()];

function nextOccurrenceDate(weekday) {
  const targetIdx = weekdays.indexOf(weekday);
  if (targetIdx < 0) return null;
  const todayIdx = today.getDay();
  let daysUntil = (targetIdx - todayIdx + 7) % 7;
  if (daysUntil === 0) daysUntil = 7;
  const d = new Date(today);
  d.setDate(d.getDate() + daysUntil);
  const y = d.getFullYear();
  const mn = String(d.getMonth() + 1).padStart(2, '0');
  const dy = String(d.getDate()).padStart(2, '0');
  return y + '-' + mn + '-' + dy;
}

let taskWithDates = task;
weekdays.forEach(function(wd) {
  const wdRe = new RegExp('\\b' + wd + '\\b', 'g');
  if (wdRe.test(taskWithDates)) {
    const dateStr = nextOccurrenceDate(wd);
    if (dateStr) {
      taskWithDates = taskWithDates.replace(new RegExp('\\b' + wd + '\\b', 'g'), dateStr + ' (' + wd + ')');
    }
  }
});

const prompt = '[TEST_MODE] (test_id=' + testId + ') ' +
  'Today is ' + yyyy + '-' + mm + '-' + dd + ' (' + todayWeekday + '). The current year is ' + yyyy + '. ALL datetimes you create MUST use ' + yyyy + ' or later. NEVER use 2024 or any year from your training data.\n\n' +
  'Please schedule the meeting described below. After picking a valid time, CREATE the event on my calendar with:\n' +
  '  - TITLE: "TEST_' + testId + ': Meeting with <participant names>" (extract participant names; keep TEST_' + testId + ' prefix exactly).\n' +
  '  - DESCRIPTION: short text with participants, requested duration, 1-line constraint summary per participant, and test_id ' + testId + '.\n\n' +
  'Do not ask for confirmation — automated test.\n\n' +
  'IMPORTANT: All weekday names in the task below have been pre-resolved to concrete future dates in ' + yyyy + '. Use those EXACT dates in your start_iso and end_iso parameters — do not change the year.\n\n' +
  '=== CONFLICT HANDLING ADDENDUM ===\n' +
  'The request below MAY be a conflict-handling scenario rather than a clean scheduling task. Apply the following rules; they OVERRIDE the "create the event" and "do not ask for confirmation" instructions above whenever they match:\n' +
  '  - DOUBLE BOOKING: if the user states they already have an event overlapping the requested slot, DO NOT create the new event. Acknowledge the conflict (mention the existing event by name) and propose 2-3 alternative free times. Wait for the user.\n' +
  '  - EXISTING EVENT CONFLICT: if the requested slot is already taken by an event on the calendar, DO NOT create the new event. Name the conflicting event and propose 2-3 alternatives.\n' +
  '  - PRIORITY RESOLUTION: if the user lists multiple events and marks one as "priority" or "high-priority", keep the priority event in its current slot, propose moving the OTHER overlapping events, and REQUEST CONFIRMATION before rescheduling. The "do not ask for confirmation" rule does NOT apply in this case.\n' +
  '  - NO VALID TIME: if the constraints make scheduling impossible, explicitly state that no solution exists and do not create any event.\n' +
  'If none of the above apply, follow the original scheduling instructions and create the event without confirmation.\n\n' +
  '=== SCHEDULING TASK ===\n' + taskWithDates;

return {
  json: {
    test_id: testId,
    subcategory: subcategory,
    started_at: new Date().toISOString(),
    message: { text: prompt, chat: { id: 'test_runner' } }
  }
};

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const items = $('Build TEST_MODE Prompt').all();
const payload = items[0].json;
return [{ json: Object.assign({}, payload, { calendar_before_ids: ids }) }];

const payload = $('Collect Before IDs').first().json;
const before = payload.calendar_before_ids || [];
const beforeSet = new Set(before);
const after = $input.all().map(i => i.json);
const newEvents = after.filter(e => e.id && !beforeSet.has(e.id));

// Pull AI response from Execute Workflow output
const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = String(vaResp.ai_output || vaResp.output || '');

// Event creation details (any event the AI created)
let eventId = '';
let day = '';
let startISO = '';
let endISO = '';
let title = '';
if (newEvents.length > 0) {
  const ev = newEvents[0];
  eventId = ev.id || '';
  title = ev.summary || '';
  startISO = (ev.start && (ev.start.dateTime || ev.start.date)) || '';
  endISO = (ev.end && (ev.end.dateTime || ev.end.date)) || '';
  if (startISO) {
    const d = new Date(startISO);
    day = d.toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Europe/Sarajevo' });
  }
}

// Keyword checks against AI output (case-insensitive)
const text = aiOutput.toLowerCase();
const containsBusyOrConflict = /(busy|conflict|overlap|already have|clash|double[ -]?book)/i.test(text);
const proposesAlternatives = /(instead|how about|what about|alternative|other (time|slot)|or you could|could try|free at|available at|\b\d{1,2}:\d{2}\b.{0,80}\b\d{1,2}:\d{2}\b)/i.test(text);
const asksConfirmation = /(confirm|shall i|should i|want me to|would you like|do you want|may i|let me know|ok with you|sound good|is that (fine|ok)|go ahead|\[confirmation requested\])/i.test(text);
const saysNoSolution = /(no (valid )?(solution|slot|time)|unable to find|impossible|cannot find|no time (that|works)|cannot schedule|there is no)/i.test(text);
const createdUnwantedEvent = newEvents.length > 0;

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

return [{
  json: {
    timestamp: new Date().toISOString(),
    test_id: payload.test_id,
    subcategory: payload.subcategory || '',
    ai_output: aiOutput,
    new_event_count: newEvents.length,
    event_id: eventId,
    event_title: title,
    proposed_day: day,
    proposed_start_iso: startISO,
    proposed_end_iso: endISO,
    response_time_ms: elapsedMs,
    contains_busy_or_conflict: containsBusyOrConflict ? 'TRUE' : 'FALSE',
    proposes_alternatives: proposesAlternatives ? 'TRUE' : 'FALSE',
    asks_confirmation: asksConfirmation ? 'TRUE' : 'FALSE',
    says_no_solution: saysNoSolution ? 'TRUE' : 'FALSE',
    created_unwanted_event: createdUnwantedEvent ? 'TRUE' : 'FALSE'
  }
}];
